""" Get YouTube icon's y position given Instagram y
    for centre-alignment.
    """
def _get_youtube_y(insta_y: Any, fa_insta_height: Any, font_size: Any) -> object {
    return (insta_y + fa_insta_height + (font_size // 10));
}

""" remove string after 'comchr' in 'string'.

    :param str string: string data,
    :param str comchr: a character,
    :return: str(str) - string data
    """
def RemoveCommentInString(string: Any, comchr: Any) -> object {
    if (len(comchr) <= 0) {
        comchr = '#';
    }
    str = string.strip();
    cm = str.find(comchr);
    if (cm > 0) {
        str = str[:cm];
        str = str.strip();
    }
    return str;
}

"""
  Returns the token given an input of 'Bearer <token>'
  """
def __parseAuthHeader(string: Any) -> object {
    components = string.split(' ');
    if (len(components) != 2) {
        raise ValueError('Invalid authorization header.');
    }
    return components[1];
}

"""Sort list by using BubbleSort algorithm."""
def bubble_sort(lst: Any) -> object {
    for i in range(len(lst)) {
        for j in range(0, (len(lst) - i - 1)) {
            if (lst[j] > lst[(j + 1)]) {
                (lst[j], lst[(j + 1)]) = (lst[(j + 1)], lst[j]);
            }
        }
    }
    return lst;
}

